SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "AVL tree"@en "B-tree"@en "Big O notation"@en "NP-complete"@en "NP-hard"@en "Turing machine"@en "abstract syntax tree"@en "adjacency list"@en "adjacency matrix"@en "amortized analysis"@en "array"@en "asymptotic analysis"@en "average case"@en "avl tree"@en "b-tree"@en "backtracking"@en "balanced tree"@en "big o notation"@en "binary heap"@en "binary search"@en "binary search tree"@en "binary tree"@en "branch and bound"@en "breadth-first search"@en "bubble sort"@en "compiler"@en "computability"@en "computational complexity"@en "context-free grammar"@en "counting sort"@en "data structure"@en "depth-first search"@en "deque"@en "deterministic finite automaton"@en "disjoint set"@en "divide and conquer"@en "dynamic programming"@en "edge"@en "exponential time"@en "finite automaton"@en "formal language"@en "graph"@en "greedy algorithm"@en "halting problem"@en "hash collision"@en "hash function"@en "hash table"@en "heap"@en "heap sort"@en "insertion sort"@en "interpreter"@en "iteration"@en "lexer"@en "linear search"@en "linked list"@en "maximum flow"@en "memoization"@en "merge sort"@en "minimum spanning tree"@en "nondeterministic finite automaton"@en "np-complete"@en "np-hard"@en "parser"@en "polynomial time"@en "priority queue"@en "pushdown automaton"@en "queue"@en "quicksort"@en "radix sort"@en "recursion"@en "red-black tree"@en "regular expression"@en "segment tree"@en "semantics"@en "shortest path"@en "sorting"@en "space complexity"@en "stack"@en "syntax"@en "tail recursion"@en "time complexity"@en "topological sort"@en "trie"@en "turing machine"@en "vertex"@en "worst case"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
